/* Live, unknown-first entry workspace. Inputs stay separate from sample-case fixtures. */
(()=>{
let active=true,editingId=null,notice='',last=null,dirty=false,attempted=false;
let stored;try{stored=JSON.parse(localStorage.getItem('fn-intake-draft-v1'))}catch{}
let current=stored?.input||FNIntakeCore.blank(),context=stored?.context||{};
const schema=fnA2A.inputSchema;
const keyLabels={...schema.labels,triageAt:'Triage / presentation time',onsetAt:'Reported fever onset (optional)',lastDoseAt:'Last antibiotic dose time',alias:'Training patient label (optional)',history:'History / source concerns (optional)',priorRegimen:'Current antibiotic regimen (if already treated)',cbcStatus:'CBC / ANC status',renalStatus:'Renal laboratory status',liverStatus:'Liver / inflammatory tests status',cultureStatus:'Blood culture collection status'};
const sections=[['1','Presentation & fever criteria','Record the current findings. Unknown values stay unknown.',['age','cancer','category','chemo','chemoDay','temp','method','feverHours','anc','expectedDecline']],['2','Vitals & immediate safety screen','The score does not override hypotension, hypoxia, confusion or other clinical concern.',['sbp','dbp','hr','rr','spo2','newHypoxia','confusion','setting']],['3','MASCC & additional clinical risk','MASCC is calculated from its components; do not enter a preselected risk score.',['burden','copd','priorFungal','dehydration','prolonged','mucositis','pneumonia','lineInfection','abdomen','majorComorbidity','mrsa']],['4','Renal dosing, allergy & previous treatment','These inputs control whether a medication reference can be shown.',['crcl','renalState','dialysis','dialysisToday','sex','weight','height','weightVerified','allergy','allergyDrug','resistance','fqProphylaxis','priorAntibiotic','persistentDays']],['5','Outpatient suitability','A reassuring score alone cannot authorize outpatient management.',['oralIntake','support','transport','followup']]];
function field(k){const label=esc(keyLabels[k]),v=current[k],range=FNAction.ranges[k];let control;if(FNAction.bools.includes(k))control=`<select name="${k}"><option value="" ${v==null?'selected':''}>Unknown / not assessed</option><option value="true" ${v===true?'selected':''}>Yes</option><option value="false" ${v===false?'selected':''}>No</option></select>`;else if(FNAction.enums[k])control=`<select name="${k}">${FNAction.enums[k].map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`;else control=`<input name="${k}" value="${esc(v??'')}" ${range?`type="number" min="${range[0]}" max="${range[1]}" step="any"`:'maxlength="200"'} placeholder="Not entered">`;return `<label class="intake-field" data-field="${k}">${label}${control}</label>`}
function metaField(k,type='text',options){const v=context[k]||'';return `<label class="intake-field" data-field="ctx_${k}">${esc(keyLabels[k])}${options?`<select name="ctx_${k}">${options.map(o=>`<option ${o===v?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input name="ctx_${k}" type="${type}" ${type==='datetime-local'?'':`maxlength="${k==='history'?800:200}"`} value="${esc(type==='datetime-local'&&v?localInput(v):v)}">`}</label>`}
function html(){return header('Assessment → suggested pathway','Enter the findings. See what needs review now, next and within the first hour.','')+`<div class="intake-scope"><b>Adult oncology · FN assessment workspace</b><p>Training decision support · enter fictional or approved test data only. Suggested pathways require bedside judgment and local clinical approval. No orders or emergency notifications are sent.</p></div><div class="intake-tabs"><span class="active">New assessment</span><button onclick="fnIntake.library()">Scenario library</button><button onclick="go('Overview')">Patient registry</button></div><section class="tta-intake"><h3>Time-to-antibiotic monitoring</h3><p>Enter the actual triage time below. The live first-hour clock appears beside your suggested pathway. Saving opens this patient’s care plan; the team dashboard tracks shared visits.</p><button type="button" class="btn" onclick="FNTTA.open()">Open shared time-to-antibiotic dashboard</button></section><div id="intake-mobile-status" class="intake-mobile-status"></div><div class="intake-layout"><form id="intake-form" class="intake-inputs" novalidate><div id="intake-validation" hidden tabindex="-1" role="alert"></div><section class="panel"><div class="sectiontitle"><div><span class="intake-eyebrow">ENCOUNTER CONTEXT</span><h2>Start with the patient assessment</h2>${context.sourcePatientId?`<p>Linked source patient: <b>${esc(context.sourcePatientId)}</b></p>`:''}</div><button type="button" class="btn" onclick="fnIntake.now()">Use now as triage</button></div><div class="intake-fields">${metaField('alias')}${metaField('triageAt','datetime-local')}${metaField('onsetAt','datetime-local')}${metaField('history')}</div><p class="mini">Fever onset is context. Confirm the measured temperature and sustained fever duration separately below.</p></section>${sections.map(([n,title,help,keys])=>`<section class="panel"><div class="intake-section-title"><span>${n}</span><div><h2>${title}</h2><p>${help}</p></div></div>${n==='3'?'<button type="button" class="btn intake-screen" onclick="fnIntake.negativeRisk()">Screened: no listed additional risk features</button><p class="mini">Sets prolonged neutropenia, severe mucositis, pneumonia, line infection, enterocolitis, major comorbidity and MRSA concern to No. Use only after assessing each.</p>':''}<div class="intake-fields">${keys.map(field).join('')}</div>${n==='4'?`<div class="intake-fields intake-subfields">${metaField('priorRegimen')}${metaField('lastDoseAt','datetime-local')}</div>`:''}</section>`).join('')}<section class="panel"><span class="intake-eyebrow">WORK-UP ALREADY REQUESTED?</span><h2>Assess what is still required</h2><p>Operator-reported status helps avoid repeating work. It does not certify collection or validate a result.</p><div class="intake-fields">${['cbcStatus','renalStatus','liverStatus'].map(k=>metaField(k,'text',FNIntakeCore.statuses)).join('')}${metaField('cultureStatus','text',['Not documented','Not collected','Collected / pending','Result available'])}</div></section><section class="panel intake-save"><h2>Save a reviewable assessment</h2><p>Saving creates or updates an entered assessment in the patient registry. It does not approve the plan, complete care, or create laboratory/culture results.</p><div class="actions"><button class="btn primary" type="submit">Save assessment & open action plan</button><button class="btn" type="button" onclick="fnIntake.export()">Export current suggestion</button><button class="btn" type="button" onclick="fnIntake.newEntry()">Start another blank assessment</button></div><p id="intake-save-note" role="status">${esc(notice)}</p></section></form><aside class="intake-output" aria-label="Live suggested pathway"><div id="intake-live" aria-live="polite"></div></aside></div>`}
function read(){const f=document.querySelector('#intake-form');if(!f)return;const data=new FormData(f);for(const k of Object.keys(current)){if(!data.has(k))continue;const v=String(data.get(k));current[k]=FNAction.bools.includes(k)?v===''?null:v==='true':FNAction.ranges[k]?v===''?null:Number(v):v}for(const [k,v]of data)if(k.startsWith('ctx_'))context[k.slice(4)]=v;try{localStorage.setItem('fn-intake-draft-v1',JSON.stringify({input:current,context,editingId}))}catch{notice='Device storage unavailable; export this draft before leaving.'}}
function markFields(){
 const form=document.querySelector('#intake-form');if(!form)return [];
 let issues=FNIntakeCore.validation(current,context).filter(x=>attempted||x.kind==='invalid');
 for(const el of form.querySelectorAll('input,select'))if(el.validity?.badInput){issues=issues.filter(x=>x.field!==el.name);issues.unshift({field:el.name,message:'Enter a valid number.',kind:'invalid'})}
 for(const label of form.querySelectorAll('[data-field]')){
  const el=label.querySelector('input,select'),issue=issues.find(x=>x.field===el.name);let note=label.querySelector('.intake-field-error');
  label.classList.toggle('intake-invalid',!!issue);
  if(issue){if(!note){note=document.createElement('span');note.className='intake-field-error';note.id='intake-error-'+el.name;label.append(note)}note.textContent=issue.message;el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',note.id)}
  else{note?.remove();el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby')}
 }
 const summary=document.querySelector('#intake-validation');summary.hidden=!issues.length;
 summary.innerHTML=issues.length?`<b>${issues.some(x=>x.kind==='invalid')?'Correct invalid values':'Information to verify'} · ${issues.length} fields</b><p>Select an item to go to its field. Red fields need correction or clinical verification; unknown values remain unknown.</p><ul>${issues.map(x=>`<li><button type="button" data-intake-focus="${esc(x.field)}">${esc(keyLabels[x.field.replace(/^ctx_/,'')]||x.field)} — ${esc(x.message)}</button></li>`).join('')}</ul>`:'';
 summary.onclick=e=>{const button=e.target.closest('[data-intake-focus]');if(button){const el=form.elements.namedItem(button.dataset.intakeFocus);el?.focus();el?.scrollIntoView({block:'center',behavior:'smooth'})}};
 return issues;
}
function focusIssue(){const key=FNIntakeCore.validation(current,context).find(x=>x.kind==='invalid')?.field;const el=(key?document.querySelector('#intake-form').elements.namedItem(key):null)||document.querySelector('#intake-form [aria-invalid="true"]');el?.focus();el?.scrollIntoView({block:'center',behavior:'smooth'})}
function humanGap(s){if(s.startsWith('Verify '))return keyLabels[s.slice(7)]||s.slice(7);return keyLabels[s]||s}
function output(){const target=document.querySelector('#intake-live');if(!target||document.activeElement?.closest('.abx-choices'))return;markFields();try{last=FNIntakeCore.evaluate(current,context);if(window.fnDyn)last=fnDyn.policySuggestion(last,context.sourcePatientId||(editingId?'SIM-'+editingId:null));const r=last;const bar=document.querySelector('#intake-mobile-status');if(bar)bar.innerHTML=`<b>${esc(r.risk)}</b><span>MASCC ${r.mascc.score??'incomplete'} · ${r.required.length} verification items</span><button class="btn" onclick="fnIntake.showTrack()">View suggested track ↓</button>`;const urgent=r.risk.includes('instability'),drugReady=r.meds.length&&!r.meds.some(m=>m.blocked);target.innerHTML=`<section class="intake-route ${urgent?'urgent':''}"><span class="intake-eyebrow">LIVE SUGGESTED TRACK</span><h2>${esc(r.risk)}</h2>${r.localPolicy?`<p>Local policy: ${esc(r.localPolicy.name)} v${r.localPolicy.version} · ${esc(r.localPolicy.status)}</p>`:''}<p>${esc(r.fn)} · ${r.outpatient?'Outpatient eligibility review':r.risk.startsWith('High')?'Inpatient / urgent review':'Complete assessment and clinician review'}</p><div class="intake-metrics"><div><small>Calculated MASCC</small><strong>${r.mascc.score??'—'}<span> / 26</span></strong></div><div><small>Time to antibiotic</small><b data-tta-intake-clock>${esc(r.antibioticClock)}</b></div></div><p>${urgent?'Urgent bedside escalation takes precedence over finishing this form.':'The display is a suggestion; it does not establish a diagnosis or authorize disposition.'}</p></section><section class="panel"><h2>${r.required.length?'Required information / verification':'Assessment inputs recorded'}</h2>${r.required.length?`<ul class="intake-gaps">${r.required.slice(0,6).map(x=>`<li>${esc(humanGap(x))}</li>`).join('')}</ul>${r.required.length>6?`<details><summary>${r.required.length-6} more items to verify</summary><ul>${r.required.slice(6).map(x=>`<li>${esc(humanGap(x))}</li>`).join('')}</ul></details>`:''}`:'<p>Review the complete findings, current medicines and local protocol before approval.</p>'}<details><summary>Why this track? MASCC & overrides</summary>${r.reasons.map(x=>`<p>${esc(x)}</p>`).join('')}${r.mascc.parts.map(x=>`<p>${esc(x.name)}: <b>${x.points??'Unknown'}</b></p>`).join('')}</details></section><section class="panel"><h2>Required now → next</h2><p class="mini">Suggested tasks · none marked completed</p>${r.tasks.map((t,i)=>`<article class="intake-task"><span>${i+1}</span><div><small>${esc(t.phase)} · ${esc(t.owner)}</small><b>${esc(t.text)}</b><p>${esc(t.state)}</p>${t.code==='therapy'?'<button type="button" class="btn" onclick="fnIntake.showAntibiotics()">View suggested antibiotic order set ↓</button>':''}</div></article>`).join('')}</section>${fnAntibioticOrders.render(r,r.input,{...r.context,patientId:r.context.sourcePatientId||(editingId?'SIM-'+editingId:''),protocol:r.localPolicy,provenance:editingId?'Previously saved assessment inputs · verify current findings':'Live entered assessment inputs · not yet saved'},'intake',true)}<section class="panel"><details><summary>Evidence & scope</summary><p>Adult training decision support. Existing FN dosing references are reused; this interface is not clinically validated. Unknown is never converted to No. No sample-case laboratory results are imported into a new assessment.</p><p><a target="_blank" rel="noopener" href="https://www.nice.org.uk/guidance/cg151/chapter/recommendations">NICE CG151: initial work-up</a></p><p><a target="_blank" rel="noopener" href="${FNAction.refs.outpatient.url}">ASCO/IDSA: first hour, risk and outpatient review</a></p></details></section>`;}catch(e){last=null;const bar=document.querySelector('#intake-mobile-status');if(bar)bar.textContent='Check the entered values — suggestions withheld.';target.innerHTML=`<section class="panel"><h2>Check the entered values</h2><p class="notice" role="alert">${esc(e.message)}</p><p>No medication suggestion is shown while a value is invalid. Suspected serious infection still requires urgent bedside review.</p></section>`}}
function bind(){const form=document.querySelector('#intake-form');if(!form)return;form.addEventListener('input',()=>{dirty=true;read();output()});form.addEventListener('change',e=>{if(e.target.name==='allergy'&&e.target.value==='None'){current.allergyDrug='None';form.elements.allergyDrug.value='None'}dirty=true;read();output()});form.onsubmit=e=>{e.preventDefault();fnIntake.save()};output()}
function keep(){read();try{localStorage.setItem('fn-intake-draft-v1',JSON.stringify({input:current,context,editingId}))}catch{}}
window.fnIntake={tickClock(){const node=document.querySelector('[data-tta-intake-clock]');if(!active||!node)return;try{let r=FNIntakeCore.evaluate(current,context);if(window.fnDyn)r=fnDyn.policySuggestion(r,context.sourcePatientId||(editingId?'SIM-'+editingId:null));node.textContent=r.antibioticClock}catch{}},showAntibiotics(){document.querySelector('#abx-intake')?.scrollIntoView({block:'start',behavior:'smooth'})},showTrack(){document.querySelector('.intake-output')?.scrollIntoView({block:'start',behavior:'smooth'})},open(){active=true;go('Patient assessment');},library(){keep();active=false;go('Scenario library')},now(){context.triageAt=new Date().toISOString();const el=document.querySelector('[name="ctx_triageAt"]');if(el)el.value=localInput(context.triageAt);keep();output()},negativeRisk(){for(const k of ['prolonged','mucositis','pneumonia','lineInfection','abdomen','majorComorbidity','mrsa']){current[k]=false;document.querySelector('#intake-form').elements[k].value='false'}keep();output()},newEntry(){keep();fnAntibioticOrders.resetDraft();attempted=false;current=FNIntakeCore.blank();context={};editingId=null;notice='New blank assessment. Previous saved patient records are retained.';dirty=false;render()},export(){read();output();if(last)download('FN_entered_assessment_suggested_pathway.json',{syntheticOnly:true,generatedAt:new Date().toISOString(),...last,antibioticOrderSet:fnAntibioticOrders.intakeExport()})},save(allowIncomplete=false){attempted=true;read();output();const issues=markFields();if(issues.some(x=>x.kind==='invalid')){document.querySelector('#intake-save-note').textContent='Correct the red invalid fields before saving.';focusIssue();return}if(issues.length&&!allowIncomplete){document.querySelector('#intake-save-note').innerHTML='Review the red verification fields before opening the plan. <button type="button" class="btn" onclick="fnIntake.save(true)">Save incomplete assessment & open draft plan</button>';focusIssue();return}if(!last){document.querySelector('#intake-save-note').textContent='Correct the invalid values before saving.';focusIssue();return}try{const key=editingId||'USR-'+crypto.randomUUID().replaceAll('-','').slice(0,24),c=FNIntakeCore.makeCase(key,current,context);fnA2A.registerEntered(c);fnAntibioticOrders.linkIntake(c.patientId);editingId=key;dirty=false;keep();active=false;fnA2A.openCase(key);if(window.fnShell)fnShell.patient(encodeURIComponent(c.patientId),'','Care plan')}catch(e){document.querySelector('#intake-save-note').textContent=e.message}},edit(c){attempted=false;current=structuredClone(c.input);context=structuredClone(c.intakeContext||{});editingId=c.id;active=true;notice='Editing entered assessment. Saving invalidates the prior local plan review.';go('Patient assessment')}};
fnIntake.fromWorkbook=function(input,meta,caseId){keep();attempted=false;current=structuredClone(input);context={alias:meta.label,history:meta.history||'',sourcePatientId:meta.patientId};editingId=caseId;active=true;dirty=false;notice='Loaded workbook inputs for '+meta.patientId+'. Verify unknown allergy, measurement method, timing and other gaps. Imported answer-key medication text is not applied.';go('Patient assessment')};
setInterval(()=>{if(!document.hidden&&view==='Patient assessment')fnIntake.tickClock()},5000);
const overviewBefore=overview;overview=function(){return overviewBefore().replace('onclick="openAssessment(true)"','onclick="fnIntake.open()"').replace('＋ New synthetic case','＋ New assessment')};
const navBefore=renderNavigation;renderNavigation=function(){return navBefore().replace('onclick="go(\'Patient assessment\')"','onclick="fnIntake.open()"')};
const renderBefore=render;render=function(){renderBefore();if(view==='Patient assessment'&&active){document.querySelector('#app').innerHTML=html();bind()}};
const openBefore=openPatient;openPatient=function(...args){keep();active=false;return openBefore(...args)};
for(const name of ['openCase','openShared']){const old=fnA2A[name];fnA2A[name]=function(...args){keep();active=false;return old(...args)}}
const showBefore=fnA2A.show;fnA2A.show=function(...args){active=false;return showBefore(...args)};
setInterval(()=>{if(active&&view==='Patient assessment'&&!document.hidden)output()},15000);
document.addEventListener('visibilitychange',()=>{if(active&&view==='Patient assessment'&&!document.hidden)output()});
editingId=stored?.editingId||null;
})();
